                "\u0420\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u0435\u0442": "\u0417\u0430\u043a\u0430\u0437\u0447\u0438\u043a                        \u0410\u0414\u041c\u0418\u041d\u0418\u0421\u0422\u0420\u0410\u0426\u0418\u042f \u0421\u0415\u041b\u042c\u0421\u041a\u041e\u0413\u041e \u041f\u041e\u0421\u0415\u041b\u0415\u041d\u0418\u042f \u0411\u0418\u0416\u0411\u0423\u041b\u042f\u041a\u0421\u041a\u0418\u0419 \u0421\u0415\u041b\u042c\u0421\u041e\u0412\u0415\u0422 \u041c\u0423\u041d\u0418\u0426\u0418\u041f\u0410\u041b\u042c\u041d\u041e\u0413\u041e \u0420\u0410\u0419\u041e\u041d\u0410 \u0411\u0418\u0416\u0411\u0423\u041b\u042f\u041a\u0421\u041a\u0418\u0419 \u0420\u0410\u0419\u041e\u041d \u0420\u0415\u0421\u041f\u0423\u0411\u041b\u0418\u041a\u0418 \u0411\u0410\u0428\u041a\u041e\u0420\u0422\u041e\u0421\u0422\u0410\u041d",
                "\u041d\u0430\u0438\u043c\u0435\u043d\u043e\u0432\u0430\u043d\u0438\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u0430 \u0437\u0430\u043a\u0443\u043f\u043a\u0438": "\u0411\u043b\u0430\u0433\u043e\u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u00ab\u041f\u0430\u0440\u043a\u0430 \u041f\u043e\u0431\u0435\u0434\u044b\u00bb, \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u043e \u0430\u0434\u0440\u0435\u0441\u0443: \u0420\u0411, \u0411\u0438\u0436\u0431\u0443\u043b\u044f\u043a\u0441\u043a\u0438\u0439 \u0440\u0430\u0439\u043e\u043d, \u0441. \u0411\u0438\u0436\u0431\u0443\u043b\u044f\u043a, \u0443\u043b. \u041f\u043e\u0431\u0435\u0434\u044b.",
                "\u042d\u0442\u0430\u043f \u0437\u0430\u043a\u0443\u043f\u043a\u0438": "\u041f\u043e\u0434\u0430\u0447\u0430 \u0437\u0430\u044f\u0432\u043e\u043a",
                "\u0421\u0432\u0435\u0434\u0435\u043d\u0438\u044f \u043e \u0441\u0432\u044f\u0437\u0438 \u0441 \u043f\u043e\u0437\u0438\u0446\u0438\u0435\u0439 \u043f\u043b\u0430\u043d\u0430-\u0433\u0440\u0430\u0444\u0438\u043a\u0430": "202001013000401001000012",
                "\u041d\u043e\u043c\u0435\u0440 \u0442\u0438\u043f\u043e\u0432\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430, \u0442\u0438\u043f\u043e\u0432\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430": "\u0421\u0432\u044f\u0437\u044c \u0441 \u0442\u0438\u043f\u043e\u0432\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u043c, \u0442\u0438\u043f\u043e\u0432\u044b\u043c\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c\u0438 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430 \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0430",
                "\u041e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u044f, \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u044e\u0449\u0430\u044f \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435": "\u0410\u0414\u041c\u0418\u041d\u0418\u0421\u0422\u0420\u0410\u0426\u0418\u042f \u0421\u0415\u041b\u042c\u0421\u041a\u041e\u0413\u041e \u041f\u041e\u0421\u0415\u041b\u0415\u041d\u0418\u042f \u0411\u0418\u0416\u0411\u0423\u041b\u042f\u041a\u0421\u041a\u0418\u0419 \u0421\u0415\u041b\u042c\u0421\u041e\u0412\u0415\u0422 \u041c\u0423\u041d\u0418\u0426\u0418\u041f\u0410\u041b\u042c\u041d\u041e\u0413\u041e \u0420\u0410\u0419\u041e\u041d\u0410 \u0411\u0418\u0416\u0411\u0423\u041b\u042f\u041a\u0421\u041a\u0418\u0419 \u0420\u0410\u0419\u041e\u041d \u0420\u0415\u0421\u041f\u0423\u0411\u041b\u0418\u041a\u0418 \u0411\u0410\u0428\u041a\u041e\u0420\u0422\u041e\u0421\u0422\u0410\u041d",
                "\u041f\u043e\u0447\u0442\u043e\u0432\u044b\u0439 \u0430\u0434\u0440\u0435\u0441": "\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0430\u044f \u0424\u0435\u0434\u0435\u0440\u0430\u0446\u0438\u044f, 452040, \u0411\u0430\u0448\u043a\u043e\u0440\u0442\u043e\u0441\u0442\u0430\u043d \u0420\u0435\u0441\u043f, \u0411\u0438\u0436\u0431\u0443\u043b\u044f\u043a\u0441\u043a\u0438\u0439 \u0440-\u043d, \u0411\u0438\u0436\u0431\u0443\u043b\u044f\u043a \u0441, \u0423\u041b\u0418\u0426\u0410 \u0422\u0420\u0423\u0414\u041e\u0412\u0410\u042f, 13",
                "\u041c\u0435\u0441\u0442\u043e \u043d\u0430\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f": "\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0430\u044f \u0424\u0435\u0434\u0435\u0440\u0430\u0446\u0438\u044f, 452040, \u0411\u0430\u0448\u043a\u043e\u0440\u0442\u043e\u0441\u0442\u0430\u043d \u0420\u0435\u0441\u043f, \u0411\u0438\u0436\u0431\u0443\u043b\u044f\u043a\u0441\u043a\u0438\u0439 \u0440-\u043d, \u0411\u0438\u0436\u0431\u0443\u043b\u044f\u043a \u0441, \u0423\u041b\u0418\u0426\u0410 \u0422\u0420\u0423\u0414\u041e\u0412\u0410\u042f, 13",
                "\u041e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0434\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u043d\u043e\u0435 \u043b\u0438\u0446\u043e": "\u0421\u0435\u043c\u0451\u043d\u043e\u0432 \u0410. \u0410.",
                "\u0410\u0434\u0440\u0435\u0441 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u043e\u0439 \u043f\u043e\u0447\u0442\u044b": "cbsp09@rambler.ru",
                "\u041d\u043e\u043c\u0435\u0440 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043d\u043e\u0433\u043e \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430": "+7 (347) 432 14 32",
                "\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f": "\u0418\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442",
